import{_ as e,o as s,c as n,ag as t}from"./chunks/framework.DC2anBTf.js";const h=JSON.parse('{"title":"鉴权与守卫","description":"","frontmatter":{},"headers":[],"relativePath":"guide/auth.md","filePath":"guide/auth.md","lastUpdated":1793536832000}'),o={name:"guide/auth.md"};function i(r,a,p,l,c,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="鉴权与守卫" tabindex="-1">鉴权与守卫 <a class="header-anchor" href="#鉴权与守卫" aria-label="Permalink to &quot;鉴权与守卫&quot;">​</a></h1><h2 id="设计难点" tabindex="-1">设计难点 <a class="header-anchor" href="#设计难点" aria-label="Permalink to &quot;设计难点&quot;">​</a></h2><p>Web 时代的经验是 <code>js-cookie</code> 同步读 token，到处直接取。但 uni-app x 的持久化（ux-storage）是<strong>异步</strong>的，而守卫、请求拦截器都是「同步心智」——直接 async/await 传染会污染整条调用链。</p><p>解法是<strong>内存缓存 + 显式就绪原语</strong>（<code>utils/auth.uts</code>）：</p><ul><li>写入时「内存即时生效 + 异步落盘」，读取永远是同步的；</li><li><code>ensureAuthReady()</code>：冷启动时由守卫链首行 <code>await</code> 调用，从持久层恢复内存缓存。内部 Promise 复用——只读一次持久层，并发调用共享同一 Promise，无竞态。</li></ul><p>异步被压缩在启动的一瞬间，之后的整条链路（守卫、拦截器、页面）回到同步心智。</p><h2 id="数据流" tabindex="-1">数据流 <a class="header-anchor" href="#数据流" aria-label="Permalink to &quot;数据流&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span>登录 → setToken（内存即时生效 + ux-storage 异步落盘）</span></span>
<span class="line"><span>     → 请求拦截器注入 Authorization: Bearer</span></span>
<span class="line"><span>冷启动 → ensureAuthReady() 先行恢复内存缓存 → 守卫链正常工作</span></span></code></pre></div><h2 id="守卫链-router-permission-uts" tabindex="-1">守卫链（router/permission.uts） <a class="header-anchor" href="#守卫链-router-permission-uts" aria-label="Permalink to &quot;守卫链（router/permission.uts）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span>await ensureAuthReady()</span></span>
<span class="line"><span>├─ 有 token</span></span>
<span class="line"><span>│   ├─ 访问登录页 → 重定向首页</span></span>
<span class="line"><span>│   ├─ 已有用户信息 → 放行</span></span>
<span class="line"><span>│   └─ 无用户信息 → await getInfoAction</span></span>
<span class="line"><span>│       ├─ 成功 → 放行</span></span>
<span class="line"><span>│       └─ 失败 → resetToken + 重定向登录页（带 redirect）</span></span>
<span class="line"><span>└─ 无 token</span></span>
<span class="line"><span>    ├─ 白名单（登录页）→ 放行</span></span>
<span class="line"><span>    └─ 其余 → 重定向登录页（query 带 redirect=path）</span></span></code></pre></div><p>白名单：<code>whiteList</code> 数组（当前仅登录页）。新页面默认要求登录，免登录页面必须同时在白名单登记。</p><h2 id="冷启动补跑" tabindex="-1">冷启动补跑 <a class="header-anchor" href="#冷启动补跑" aria-label="Permalink to &quot;冷启动补跑&quot;">​</a></h2><p>冷启动（H5 直达 / deeplink）时页面可能已加载而守卫未执行。<code>setupPermission()</code> 在 <code>router.isReady()</code> 后显式调用 <code>router.guardRoute(null, null)</code> 补跑守卫链，redirect 按 relaunch 执行。</p><h2 id="导航兜底" tabindex="-1">导航兜底 <a class="header-anchor" href="#导航兜底" aria-label="Permalink to &quot;导航兜底&quot;">​</a></h2><p>运行时启用 <code>InterceptorPlugin</code>（<code>interceptUniApi: true</code>）：外部直调的 <code>uni.navigateTo</code> 等原生导航被拦截转交守卫链。这是纵深防御——规约仍要求统一走 <code>useRouter()</code>，不得依赖兜底。</p><h2 id="职责分离" tabindex="-1">职责分离 <a class="header-anchor" href="#职责分离" aria-label="Permalink to &quot;职责分离&quot;">​</a></h2><ul><li><strong>token 读写</strong>：<code>utils/auth.uts</code>（对标 js-cookie 职责）；</li><li><strong>登录/登出动作</strong>：<code>stores/modules/user.uts</code>（loginAction / logoutAction / resetToken）；</li><li><strong>退出登录</strong>：<code>showModalAsync</code> 确认弹窗（破坏性操作标准语义）→ logoutAction 调接口（失败不阻断本地清理）→ 清状态与持久层 → relaunch 登录页。</li></ul><p>ux-pinia 0.2.0 的内置持久化插件<strong>不用于 token</strong>：避免与 ux-storage 双轨持久化语义分裂（判据详见仓库任务文档）。</p>`,18)])])}const g=e(o,[["render",i]]);export{h as __pageData,g as default};
